int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<pair<int, long long>>> adj(N);
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        u--; v--;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    vector<int> color(N, -1);
    color[0] = 0; // white = 0, black = 1

    stack<int> st;
    st.push(0);

    while (!st.empty()) {
        int u = st.top();
        st.pop();

        for (auto &[v, w] : adj[u]) {
            if (color[v] == -1) {
                if (w % 2 == 0) {
                    color[v] = color[u];
                } else {
                    color[v] = 1 - color[u];
                }
                st.push(v);
            }
        }
    }

    for (int c : color) {
        cout << c << "\n";
    }

    return 0;
}

