#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

typedef struct Edge {
    int to, next, w;
} Edge;

Edge edges[MAXN * 2];
int head[MAXN], edge_cnt;
int color[MAXN];

void add_edge(int u, int v, int w) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].w = w;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void dfs(int u, int p, int parity) {
    color[u] = parity;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        int w = edges[i].w;
        if (v == p) continue;
        dfs(v, u, (parity + (w % 2)) % 2);
    }
}

