int queue[MAXN];
int parity[MAXN]; // parity of distance from root

int main() {
    int n;
    scanf("%d", &n);

    memset(head, -1, sizeof(head));

    for (int i = 0; i < n - 1; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(u, v, w);
        add_edge(v, u, w);
    }

    memset(visited, 0, sizeof(visited));
    memset(parity, 0, sizeof(parity));

    int front = 0, back = 0;
    queue[back++] = 1;
    visited[1] = 1;
    parity[1] = 0;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].w;
            if (!visited[v]) {
                visited[v] = 1;
                parity[v] = (parity[u] + w) % 2;
                queue[back++] = v;
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        if (i > 1) printf("\n");
        printf("%d", parity[i]);
    }
    printf("\n");

