    long long w;
    int next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * (M > 0 ? M : 1));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int idx = 0;
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        long long w;
        scanf("%d %d %lld", &u, &v, &w);

        edges[idx].to = v;
        edges[idx].w = w;
        edges[idx].next = head[u];
        head[u] = idx++;

        edges[idx].to = u;
        edges[idx].w = w;
        edges[idx].next = head[v];
        head[v] = idx++;
    }

    int *color = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) color[i] = -1;

    int *queue = (int *)malloc(sizeof(int) * (N + 5));
    int front = 0, back = 0;

    color[1] = 0;
    queue[back++] = 1;

    while (front < back) {
        int u = queue[front++];

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (color[v] != -1) continue;

            color[v] = color[u] ^ (int)(edges[e].w % 2);
            queue[back++] = v;
        }
    }

    for (int i = 1; i <= N; i++) {
        printf("%d\n", color[i]);
    }

    free(edges);
    free(head);
    free(color);
    free(queue);
    return 0;
}

