            adj[v].add(new int[]{u, w});
        }

        int[] color = new int[N + 1];
        Arrays.fill(color, -1);
        color[1] = 0;

        Queue<Integer> queue = new LinkedList<>();
        queue.add(1);

        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int[] edge : adj[node]) {
                int next = edge[0];
                int w = edge[1];
                if (color[next] == -1) {
                    color[next] = (color[node] + w) % 2;
                    queue.add(next);
                }
            }
